document.querySelectorAll('[data-lab="G08-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const q=s=>root.querySelector(s),fields={};['shift','angle','deform','mode'].forEach(k=>fields[k]=q('[data-field="'+k+'"]'));const zh=root.dataset.language==='zh',ref=[[-.5,-.25],[.5,-.25],[.5,.25],[-.5,.25]],rms=p=>Math.sqrt(p.reduce((s,v,i)=>s+(v[0]-ref[i][0])**2+(v[1]-ref[i][1])**2,0)/4),points=p=>p.concat([p[0]]).map(v=>(410+100*v[0])+','+(220-100*v[1])).join(' ');function update(){let shift=+fields.shift.value,angle=+fields.angle.value*Math.PI/180,d=+fields.deform.value,c=Math.cos(angle),s=Math.sin(angle),raw=ref.map((p,i)=>{let x=p[0]+(i===2?d:0),y=p[1];return[c*x-s*y+shift,s*x+c*y]}),mean=[0,0];raw.forEach(p=>{mean[0]+=p[0]/4;mean[1]+=p[1]/4});let centered=raw.map(p=>[p[0]-mean[0],p[1]-mean[1]]),dot=0,cross=0;centered.forEach((p,i)=>{dot+=p[0]*ref[i][0]+p[1]*ref[i][1];cross+=p[0]*ref[i][1]-p[1]*ref[i][0]});let theta=Math.atan2(cross,dot),co=Math.cos(theta),si=Math.sin(theta),fit=centered.map(p=>[co*p[0]-si*p[1],si*p[0]+co*p[1]]),shown={raw,center:centered,fit}[fields.mode.value];q('[data-reference]').setAttribute('points',points(ref));q('[data-mobile]').setAttribute('points',points(shown));q('[data-points]').innerHTML=shown.map(p=>'<circle cx="'+(410+100*p[0])+'" cy="'+(220-100*p[1])+'" r="6" fill="#cb6a36"/>').join('');['shift','angle','deform'].forEach(k=>q('[data-read="'+k+'"]').textContent=Number(fields[k].value).toFixed(k==='angle'?0:2));q('[data-feedback]').textContent=(zh?'均方根偏差：原始 ':'RMS deviation: raw ')+rms(raw).toFixed(4)+(zh?' nm；仅居中 ':' nm; centered ')+rms(centered).toFixed(4)+(zh?' nm；完整对齐 ':' nm; fully fitted ')+rms(fit).toFixed(4)+' nm.';}Object.entries(fields).forEach(([k,f])=>f.addEventListener(k==='mode'?'change':'input',update));q('[data-action="reset"]').addEventListener('click',()=>{fields.shift.value=1;fields.angle.value=60;fields.deform.value=0;fields.mode.value='fit';update()});update();});